  // cube text: identity grid ko poori grading (+active LUT) se guzaar ke — sirf rang ke tools (sharpen/vignette/grain/AI/denoise/detail/lowlight/skin-smooth bahar)
  function exportCubeText(){
    const N = 33, W = N * N, cv = document.createElement('canvas'); cv.width = W; cv.height = N;
    const x = cv.getContext('2d'), id = x.createImageData(W, N);
    for(let b = 0; b < N; b++) for(let g = 0; g < N; g++) for(let r = 0; r < N; r++){ const o = (g * W + b * N + r) * 4; id.data[o] = Math.round(r / (N - 1) * 255); id.data[o + 1] = Math.round(g / (N - 1) * 255); id.data[o + 2] = Math.round(b / (N - 1) * 255); id.data[o + 3] = 255; }
    x.putImageData(id, 0, 0);
    const keep = Object.assign({}, G); ['sharpen', 'vignette', 'grain', 'aiEnh', 'denoise', 'detail', 'lowlight', 'skinSm'].forEach(k => { G[k] = 0; });
    let out = null; try{ out = glGrade(cv, W, N); }finally{ Object.assign(G, keep); }
    if(!out) throw new Error('WebGL nahi chal raha');
    const rd = document.createElement('canvas'); rd.width = W; rd.height = N; const rx = rd.getContext('2d'); rx.drawImage(out, 0, 0);
    const px = rx.getImageData(0, 0, W, N).data;
    const f = (v)=> (v / 255).toFixed(6);
    let t = '# Chat Cam look — exported LUT\nTITLE "Chat Cam Look"\nLUT_3D_SIZE ' + N + '\nDOMAIN_MIN 0.0 0.0 0.0\nDOMAIN_MAX 1.0 1.0 1.0\n';
    for(let b = 0; b < N; b++) for(let g = 0; g < N; g++) for(let r = 0; r < N; r++){ const o = (g * W + b * N + r) * 4; t += f(px[o]) + ' ' + f(px[o + 1]) + ' ' + f(px[o + 2]) + '\n'; }
    return t;
  }
  function exportCube(){
    if(isId() && !LUT.id){ toast('Pehle koi look / LUT lagao, phir export.'); return; }
    let txt; try{ txt = exportCubeText(); }catch(e){ toast('Export nahi hua: ' + e.message); return; }
    try{ const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([txt], { type: 'text/plain' })); a.download = 'chatcam-look.cube'; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); }, 1500); toast('💾 chatcam-look.cube save'); }catch(e){ toast('Download block hua'); }
  }
  function importLut(){
    const inp = document.createElement('input'); inp.type = 'file'; inp.accept = '.cube,.3dl,.txt,text/plain'; inp.style.display = 'none';
    inp.onchange = ()=>{ const f = inp.files && inp.files[0]; inp.remove(); if(!f) return;
      if(f.size > 12 * 1024 * 1024){ toast('File bahut badi (12MB max)'); return; }
      const rd = new FileReader();
      rd.onload = ()=>{ try{ const L = /\.3dl$/i.test(f.name) ? parse3dl(rd.result) : parseCube(rd.result), id = lutAdd((L.title || f.name.replace(/\.[^.]+$/, '')), L); lutPick(id); toast('🎞️ LUT lag gaya (' + L.n + '³)'); }catch(e){ toast('LUT: ' + e.message); } };
      rd.onerror = ()=> toast('File padhi nahi gayi');
      rd.readAsText(f);
    };
    document.body.appendChild(inp); inp.click();
  }
  function lutCompOff(){ Object.keys(lutComp).forEach(k => { if(G[k] === lutComp[k]) G[k] = 0; }); lutComp = {}; }
  function lutPick(id){
    if(LUT.id === id && G.lutAmt > 0){ lutOff(); lutCompOff(); G.lutAmt = 0; flushG(); paintCar(true); toast('LUT band'); return; }
    if(!lutActivate(id)){ toast('LUT load nahi hua'); return; }
    lutCompOff();
    if(!G.lutAmt) G.lutAmt = 100;
    const bm = BLUTS[id];
    if(bm && bm.g) Object.keys(bm.g).forEach(k => { if(k in G && !(G[k] > bm.g[k])){ G[k] = bm.g[k]; lutComp[k] = bm.g[k]; } });   // user ki apni zyada value ho to chhedna nahi
    flushG(); paintCar(true);
  }
