  // ROUND 31: video call / pre-call preview me camera ka saved grade+LUT lagane ke liye
  let gTmp = null, gTmpX = null;
  window.cxGradeActive = ()=> !isId();
  window.cxGradeApply = function(src, w, h, canF){
    if(isId()) return null;
    const g = glGrade(src, w, h); if(g) return g;
    if(!gTmp){ gTmp = document.createElement('canvas'); gTmpX = gTmp.getContext('2d'); }
    if(gTmp.width !== w || gTmp.height !== h){ gTmp.width = w; gTmp.height = h; }
    cssGrade(gTmpX, src, w, h, canF); return gTmp;
  };
  function glGrade(src, w, h){
    if(!glInit()) return null;
    try{
      if(glc.width !== w || glc.height !== h){ glc.width = w; glc.height = h; }
      gl.viewport(0, 0, w, h);
      gl.bindTexture(gl.TEXTURE_2D, glTex);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, src);
      const n = (k)=> G[k] / 100;
      gl.uniform2f(U.px, 1 / w, 1 / h);
      gl.uniform1f(U.ex, n('exposure')); gl.uniform1f(U.br, n('brightness')); gl.uniform1f(U.co, n('contrast')); gl.uniform1f(U.sa, n('saturation'));
      gl.uniform1f(U.vi, n('vibrance')); gl.uniform1f(U.tp, n('temp')); gl.uniform1f(U.tn, n('tint')); gl.uniform1f(U.hl, n('highlights'));
      gl.uniform1f(U.sh, n('shadows')); gl.uniform1f(U.wh, n('whites')); gl.uniform1f(U.bk, n('blacks')); gl.uniform1f(U.fd, n('fade'));
      gl.uniform1f(U.hu, n('hue')); gl.uniform1f(U.se, n('sepia')); gl.uniform1f(U.sp, n('sharpen')); gl.uniform1f(U.vg, n('vignette')); gl.uniform1f(U.gr, n('grain'));
      gl.uniform1f(U.tm, (performance.now() % 1000) * 7.13);
      gl.uniform1f(U.ai, n('aiEnh')); gl.uniform1f(U.dn, n('denoise')); gl.uniform1f(U.dt, n('detail')); gl.uniform1f(U.ll, n('lowlight')); gl.uniform1f(U.ss, (st && st.lvl >= 3) ? 0 : n('skinSm')); gl.uniform1f(U.lt, (st && st.lvl >= 1) ? 1 : 0);
      gl.uniform1f(U.sA, n('shAmt')); gl.uniform1f(U.hA, n('hiAmt'));
      gl.uniform1f(U.gm, n('gamma')); gl.uniform1f(U.kp, n('skinProt')); gl.uniform1f(U.cH, G.selHue / 360); gl.uniform1f(U.cR, G.selRange / 360);
      gl.uniform1f(U.cD, n('selShift')); gl.uniform1f(U.cS, n('selSat')); gl.uniform1f(U.cL, n('selLum'));
      const a = hsv(G.shHue / 360), b = hsv(G.hiHue / 360);
      gl.uniform3f(U.sC, a[0], a[1], a[2]); gl.uniform3f(U.hC, b[0], b[1], b[2]);
      if(lutDirty){ lutDirty = false; if(LUT.rgba){ gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, lutTex); gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, LUT.n * LUT.n, LUT.n, 0, gl.RGBA, gl.UNSIGNED_BYTE, LUT.rgba); gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true); gl.activeTexture(gl.TEXTURE0); } }
      gl.uniform1f(U.lutA, LUT.rgba ? n('lutAmt') : 0); gl.uniform1f(U.lutN, LUT.n || 2);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      return glc;
    }catch(e){ console.error('grade draw', e); glFail = true; gl = null; return null; }
  }
  // WebGL na chale to halka fallback (brightness/contrast/saturation/hue/temperature/tint/vignette)
  function cssGrade(c, src, w, h, canF){
    c.save();
    if(canF){
      const b = Math.pow(2, G.exposure / 100 * 1.2) * (1 + G.brightness / 100 * .5) * Math.pow(2, G.gamma / 100 * .45), k = 1 + G.contrast / 100 * .7, sa = (1 + G.saturation / 100) * (1 + G.vibrance / 200);
      c.filter = 'brightness(' + b + ') contrast(' + k + ') saturate(' + sa + ') hue-rotate(' + (G.hue * 1.8) + 'deg) sepia(' + (G.sepia / 100) + ')';
    }
    c.drawImage(src, 0, 0, w, h);
    c.restore();
    const wsh = (col, a, mode)=>{ c.save(); c.globalCompositeOperation = mode; c.fillStyle = 'rgba(' + col + ',' + a + ')'; c.fillRect(0, 0, w, h); c.restore(); };
    if(G.temp) wsh(G.temp > 0 ? '255,150,40' : '60,130,255', Math.abs(G.temp) / 100 * .35, 'soft-light');
    if(G.tint) wsh(G.tint > 0 ? '220,60,220' : '60,200,90', Math.abs(G.tint) / 100 * .3, 'soft-light');
    if(G.vignette > 0){ const g = c.createRadialGradient(w / 2, h / 2, Math.min(w, h) * .3, w / 2, h / 2, Math.max(w, h) * .7); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,' + (G.vignette / 100 * .8) + ')'); c.fillStyle = g; c.fillRect(0, 0, w, h); }
  }
  const curAdj = ()=> ADJ.find(a => a.k === gSel) || ADJ[1];
