      if(f.size > 1.5 * 1024 * 1024) toast('🎞 Video ' + fmtB(f.size) + ' — gallery me original save; chat ke liye ~1.5 MB tak compress hogi (trim screen).');
      try{ window.cxAutoSave && window.cxAutoSave(f); }catch(e){}
