      ell(lx, ly, lw * .26, lw * .075, roll, '255,255,255', a * .85, 'screen');
      ell(lx - (X[291] - X[61]) * .17, ly, lw * .1, lw * .05, roll, '255,255,255', a * .5, 'screen');
