        tc.globalCompositeOperation = 'soft-light'; tc.globalAlpha = clamp(a * .8, 0, 1); tc.fillRect(X[c0] - ir, Y[c0] - ir, ir * 2, ir * 2);
        tc.globalCompositeOperation = 'screen'; tc.globalAlpha = clamp(a * .16, 0, 1); tc.fillRect(X[c0] - ir, Y[c0] - ir, ir * 2, ir * 2);
