// ============================================================================
// CHAT PLUS 17: GALLERY SAVE (camera + chat media) + draw mode me sab controls chalte hain
//   - Camera se photo/video lete hi apne aap phone me save (localStorage 'cxAutoGal' = '0' kare to band).
//   - Chat ke har photo/video ke neeche "⬇ Gallery" button + viewer ka ⬇ bhi seedha save karta hai.
//   - Android: file Downloads me jati hai aur Gallery/Photos me "Download" album me dikhti hai.
//   - iPhone: browser seedha gallery me nahi likh sakta -> Share sheet khulti hai, "Save Image/Video" dabao.
//   - Draw mode (HandWrite): send, +, camera, menu, header sab ke taps ab seedha kaam karte hain.
// ============================================================================
(function cxGallery(){
  const toast = (m)=>{ try{ chatToastMsg(m); }catch(e){} };
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const EXT = { 'image/jpeg':'jpg', 'image/png':'png', 'image/webp':'webp', 'image/gif':'gif', 'video/mp4':'mp4', 'video/webm':'webm', 'video/quicktime':'mov' };

  async function toBlob(src){
    if(src instanceof Blob) return src;
    if(typeof src === 'string'){ const r = await fetch(src); return await r.blob(); }
    throw new Error('bad src');
  }
  function fixName(name, blob, kind){
    let n = String(name || '').replace(/[\\/:*?"<>|]+/g, '_');
    const ext = EXT[blob.type] || (kind === 'v' ? 'webm' : 'jpg');
    if(!/\.[a-z0-9]{2,4}$/i.test(n)) n = (n && n !== 'file' ? n : 'chat_' + Date.now()) + '.' + ext;
    return n;
  }
  async function save(src, name, kind, quiet){
    try{
      const blob = await toBlob(src);
      const fname = fixName(name, blob, kind);
      const file = new File([blob], fname, { type: blob.type || (kind === 'v' ? 'video/webm' : 'image/jpeg') });
      if(isIOS && navigator.canShare && navigator.canShare({ files:[file] })){
        await navigator.share({ files:[file] });                       // Save Image / Save Video
        return true;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = fname; a.style.display = 'none';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=> URL.revokeObjectURL(url), 30000);
      if(!quiet) toast('✅ Phone me save ho gaya (Gallery → Download album)');
      return true;
    }catch(err){
      if(err && err.name === 'AbortError') return false;               // user ne share sheet band ki
      console.error('gallery save', err); toast('Save nahi ho paya.'); return false;
    }
  }
  window.cxGallerySave = save;
  window.cxAutoSave = function(file){
    try{ if(localStorage.getItem('cxAutoGal') === '0') return; }catch(e){}
    if(isIOS) return;                                                  // iOS par share sheet auto nahi khul sakti
    save(file, file.name, /^video/.test(file.type) ? 'v' : 'i', true).then(ok=>{ if(ok) toast('📥 Camera ki file phone me save ho gayi'); });
  };

  // viewer ke ⬇ buttons (dono viewers) -> seedha gallery save
  document.addEventListener('click', (e)=>{
    const b = e.target.closest && e.target.closest('#cxvSave, #cxVsave'); if(!b) return;
    const v = b.closest('#cxvOv, #cxView'); if(!v || !v.dataset.src) return;
    e.stopImmediatePropagation(); e.preventDefault();
    const isVid = !!v.querySelector('video');
    save(v.dataset.src, v.dataset.name, isVid ? 'v' : 'i');
  }, true);

  // chat bubbles: photo/video ke neeche "⬇ Gallery"
  const css = document.createElement('style');
  css.textContent = '.cxDl{display:inline-flex;align-items:center;gap:6px;margin:6px 0 0;padding:7px 13px;border-radius:16px;border:1px solid #3a3d47;background:#23252d;color:#cfd0d4;font-size:14px;font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}.cxDl:active{background:#3a3550}.cxDl[disabled]{opacity:.6}';
  document.head.appendChild(css);
  async function onDl(e){
    e.preventDefault(); e.stopPropagation();
    const b = e.currentTarget; if(b.disabled) return; b.disabled = true; const t0 = b.textContent; b.textContent = '…';
    try{
      const d = await window.cxGetFile(b.dataset.fid);
      const blob = (typeof d === 'string') ? await (await fetch(d)).blob() : (d instanceof Blob ? d : null);
      if(!blob) throw new Error('no data');
      await save(blob, b.dataset.n, b.dataset.k);
    }catch(err){ console.error(err); toast('Ye file load nahi ho paayi.'); }
    b.disabled = false; b.textContent = t0;
  }
  function scan(){
    if(!window.cxGetFile) return;
    document.querySelectorAll('#chatMsgs img.cimg[data-fid]:not([data-dl]), #chatMsgs .cfile[data-act="vid"][data-fid]:not([data-dl])').forEach(el=>{
      el.setAttribute('data-dl', '1');
      const fid = el.dataset.fid; if(!fid) return;
      const isVid = el.classList.contains('cfile');
      const b = document.createElement('button'); b.type = 'button'; b.className = 'cxDl'; b.textContent = '⬇ Gallery';
      b.dataset.fid = fid; b.dataset.k = isVid ? 'v' : 'i'; b.dataset.n = isVid ? (el.dataset.n || 'video') : 'photo_' + Date.now() + '.jpg';
      b.addEventListener('click', onDl);
      el.insertAdjacentElement('afterend', b);
    });
  }
  cxPoll('chat', ()=>{ try{ scan(); }catch(e){} }, 700);

  // camera khule to draw overlay band (warna camera ke upar overlay aa jata)
  const t = setInterval(()=>{
    if(typeof window.cxOpenCam !== 'function' || window.cxOpenCam.__hw) return;
    const orig = window.cxOpenCam;
    window.cxOpenCam = function(){ try{ HandWrite.close(); }catch(e){} return orig.apply(this, arguments); };
    window.cxOpenCam.__hw = true; clearInterval(t);
  }, 400);
  setTimeout(()=>{ try{ clearInterval(t); }catch(e){} }, 120000);
})();


// ============================================================================
// CHAT PLUS 18: TEXT SIZE  A− / A+  (chat bubbles + type karne wala box)
//   - ROUND 33: ab chat header me alag 'Aa' button; tap par pill chat ke ANDAR khulta hai (body overlay nahi), 4s baad / bahar tap par band.
//   - (purana) Chat khulte hi right side me chhota pill: [A−] [19] [A+]. Tap = 1px kam/zyada (12–30). Beech ka number = default (19) par wapas.
//   - Save: localStorage 'cxFs'. CSS var --cxfs (#chatOverlay par). Messages ke upar do ungli pinch bhi chalta hai.
// ============================================================================
(function chatTextSize(){
  const MIN = 12, MAX = 30, DEF = 19;
  let fs = DEF; try{ const v = Number(localStorage.getItem('cxFs')); if(v >= MIN && v <= MAX) fs = v; }catch(e){}
  const css = document.createElement('style');
  css.textContent = `
  #chatOverlay{--cxfs:${fs}}
  #chatOverlay #chatMsgs .cbub{font-size:calc(var(--cxfs,19) * 1px)!important;line-height:1.5!important}
  #chatOverlay .chatComposer #chatInput{font-size:max(16px, calc(var(--cxfs,19) * 1px - 1px))!important}
  #cxFsPill{position:absolute;right:8px;top:64px;z-index:30;display:none;align-items:center;gap:2px;padding:3px;border-radius:20px;background:rgba(28,29,35,.92);border:1px solid #34363f;box-shadow:0 3px 12px rgba(0,0,0,.45);transition:opacity .4s;opacity:1}
  #cxFsPill.show{display:flex}
  #cxFsPill.dim{opacity:1}
  #cxFsBtn{font-size:14px;font-weight:800;letter-spacing:-.5px}
  #cxFsBtn.on{background:var(--accent,#fbbf24);color:#120d00}
  #cxFsPill button{border:0;background:transparent;color:#cfd0d4;font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent;padding:0}
  #cxFsPill .fsb{width:38px;height:34px;border-radius:17px;font-weight:700}
  #cxFsPill .fsb:active{background:#2b2e36}
  #cxFsPill #cxFsM{font-size:13px}#cxFsPill #cxFsP{font-size:19px}
  #cxFsPill #cxFsN{min-width:26px;height:34px;font-size:12px;color:#8b8d95}`;
  document.head.appendChild(css);

  let pill = null, dimT = 0;
  let shown = false;
  const paintBtn = ()=>{ const x = document.getElementById('cxFsBtn'); if(x) x.classList.toggle('on', shown); };
  const setShown = (v)=>{ shown = !!v; if(pill) pill.classList.toggle('show', shown); paintBtn(); clearTimeout(dimT); if(shown) dimT = setTimeout(()=> setShown(false), 4000); };
  const poke = ()=>{ if(shown){ clearTimeout(dimT); dimT = setTimeout(()=> setShown(false), 4000); } };
  function set(v, quiet){
    fs = Math.max(MIN, Math.min(MAX, Math.round(v)));
    const ov = document.getElementById('chatOverlay'); if(ov) ov.style.setProperty('--cxfs', fs);
    try{ localStorage.setItem('cxFs', String(fs)); }catch(e){}
    const n = document.getElementById('cxFsN'); if(n) n.textContent = fs;
    poke();
    try{ if(!quiet && typeof chatNearBottom === 'function' && chatNearBottom()) chatScrollBottom(); }catch(e){}
  }
  function build(){
    if(pill) return;
    pill = document.createElement('div'); pill.id = 'cxFsPill';
    pill.innerHTML = '<button type="button" class="fsb" id="cxFsM" aria-label="Text chhota">A−</button><button type="button" id="cxFsN" aria-label="Normal size">' + fs + '</button><button type="button" class="fsb" id="cxFsP" aria-label="Text bada">A+</button>';
    const cv = document.getElementById('chatConv'); if(!cv) { pill = null; return; }
    cv.appendChild(pill);
    const tap = (id, fn)=>{ const b = pill.querySelector(id); b.addEventListener('pointerdown', (e)=>{ e.preventDefault(); }); b.addEventListener('click', (e)=>{ e.preventDefault(); fn(); }); };
    // dabaye rakho to lagataar badhta/ghatta hai
    const hold = (id, d)=>{ const b = pill.querySelector(id); let t = 0, iv = 0, held = false;
      b.addEventListener('pointerdown', ()=>{ held = false; t = setTimeout(()=>{ held = true; iv = setInterval(()=> set(fs + d, true), 90); }, 380); });
      const stop = ()=>{ clearTimeout(t); clearInterval(iv); };
      b.addEventListener('pointerup', stop); b.addEventListener('pointercancel', stop); b.addEventListener('pointerleave', stop);
      b.addEventListener('click', (e)=>{ e.preventDefault(); if(held){ held = false; return; } set(fs + d); }); };
    hold('#cxFsM', -1); hold('#cxFsP', 1);
    tap('#cxFsN', ()=> set(DEF));
  }
  // pinch (do ungli) se bhi size
  function bindPinch(){
    const box = document.getElementById('chatMsgs'); if(!box || box.dataset.fsPinch) return; box.dataset.fsPinch = '1';
    let d0 = 0, f0 = fs;
    const dist = (t)=> Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
    box.addEventListener('touchstart', (e)=>{ if(e.touches.length === 2){ d0 = dist(e.touches); f0 = fs; } }, { passive: true });
    box.addEventListener('touchmove', (e)=>{ if(e.touches.length === 2 && d0){ set(f0 * dist(e.touches) / d0, true); } }, { passive: true });
    box.addEventListener('touchend', ()=>{ d0 = 0; }, { passive: true });
  }
  function ensureBtn(conv){
    if(document.getElementById('cxFsBtn')) return;
    const h = conv.querySelector('.chatHead'); if(!h) return;
    const x = document.createElement('button'); x.type = 'button'; x.id = 'cxFsBtn'; x.className = 'chatIconBtn'; x.textContent = 'Aa'; x.setAttribute('aria-label', 'Text size');
    x.addEventListener('click', ()=>{ build(); if(!pill) return; setShown(!shown); });
    h.insertBefore(x, document.getElementById('cxMoreBtn') || null);
  }
  function tick(){
    const conv = document.getElementById('chatConv');
    const open = !!(conv && !conv.hidden && conv.getClientRects().length);
    if(open){
      ensureBtn(conv); bindPinch();
      if(pill){ const h = conv.querySelector('.chatHead'); pill.style.top = ((h ? h.offsetHeight : 56) + 8) + 'px'; }
    }else if(shown){ setShown(false); }
  }
  // pill ke bahar tap = band (sirf chat ke andar ka control)
  document.addEventListener('pointerdown', (e)=>{ if(shown && !(e.target.closest && e.target.closest('#cxFsPill,#cxFsBtn'))) setShown(false); }, true);
  cxPoll('chat', ()=>{ try{ tick(); }catch(e){} }, 400);
})();

/* ===== CHAT PLUS 19: PIN + ARCHIVE chats (source: JosephPshine63/wacchat — favorites/archive) =====
   Chat list me kisi row par lamba dabao (0.5s) -> 📌 Pin / 📦 Archive menu.
   Pinned = list ke upar (📌). Archived = list se hat jaate hain, upar "📦 Archived (n)" row se dikhte hain.
   Save: localStorage 'cxPin:<me>' / 'cxArch:<me>' (is device me). Search karte waqt sab dikhta hai. */
(function chatPlus19(){
  if(window.__cxPlus19) return; window.__cxPlus19 = 1;
  let showArch = false, lp = false, tm = 0, sx = 0, sy = 0;
  const me = ()=>{ try{ return chatMyKey(); }catch(e){ return 'me'; } };
  const ld = (k)=>{ try{ const a = JSON.parse(localStorage.getItem(k + ':' + me()) || '[]'); return Array.isArray(a) ? a : []; }catch(e){ return []; } };
  const sv = (k, a)=>{ try{ localStorage.setItem(k + ':' + me(), JSON.stringify(a)); }catch(e){} };
  const kOf = (name)=>{ try{ return chatSeenKey(name); }catch(e){ return String(name).toLowerCase(); } };
  if(!document.getElementById('cxP19css')){
    const st = document.createElement('style'); st.id = 'cxP19css';
    st.textContent = '#chatOverlay .cxArchRow{display:flex;align-items:center;gap:10px;width:100%;padding:12px 14px;background:transparent;border:0;border-bottom:1px solid rgba(255,255,255,.06);color:#cfd0d4;font-size:16px;text-align:left}'
      + '#chatOverlay .cxArchRow b{margin-left:auto;background:#3a3d44;border-radius:10px;padding:1px 8px;font-size:13px}'
      + '#chatOverlay .cxArchRow b.u{background:#25a56a;color:#fff}'
      + '.cxPinMark{font-size:12px;margin-left:6px;opacity:.8}'
      + '#cxP19menu{position:fixed;inset:0;z-index:2147483000;background:rgba(0,0,0,.45);display:flex;align-items:flex-end}'
      + '#cxP19menu div{width:100%;background:#1b1c20;border-radius:16px 16px 0 0;padding:8px 0 14px}'
      + '#cxP19menu p{margin:0;padding:10px 18px;color:#8b8d94;font-size:14px}'
      + '#cxP19menu button{display:block;width:100%;padding:15px 18px;background:none;border:0;color:#e4e5e8;font-size:17px;text-align:left}';
    document.head.appendChild(st);
  }
  function menu(name){
    const k = kOf(name), pins = ld('cxPin'), arch = ld('cxArch');
    const isP = pins.includes(k), isA = arch.includes(k);
    const w = document.createElement('div'); w.id = 'cxP19menu';
    let adm = false; try{ adm = isMeAdmin() && String(name).toLowerCase() !== String(myName).toLowerCase(); }catch(_){}
    w.innerHTML = '<div><p></p><button data-a="p"></button><button data-a="a"></button>' + (adm ? '<button data-a="h"></button><button data-a="r"></button>' : '') + '</div>';
    if(adm){
      let hid = false, res = false; try{ hid = isHiddenFromOthers(name); res = isRestrictedToSelf(name); }catch(_){}
      w.querySelector('[data-a=h]').textContent = (hid ? '☑' : '☐') + ' 👑 Sirf mujhe/khud ko dikhe (baaki sabse hide)';
      w.querySelector('[data-a=r]').textContent = (res ? '☑' : '☐') + ' 👑 Isko sirf khud + mujhe (Admin) dikhaao — poore app mein';
    }
    w.querySelector('p').textContent = name;
    w.querySelector('[data-a=p]').textContent = isP ? '📌 Unpin karo' : '📌 Upar pin karo';
    w.querySelector('[data-a=a]').textContent = isA ? '📤 Archive se wapas lao' : '📦 Archive karo';
    w.addEventListener('click', (e)=>{
      const a = e.target && e.target.getAttribute && e.target.getAttribute('data-a');
      if(a === 'h' || a === 'r'){
        e.target.disabled = true; e.target.textContent = '⏳...';
        (async ()=>{
          try{
            if(a === 'h') await setMemberHidden(name, !isHiddenFromOthers(name));
            else await setMemberRestricted(name, !isRestrictedToSelf(name));
            try{ await renderCompetePanel(); }catch(_){}
          }catch(err){ console.error('admin member toggle', err); }
          w.remove(); decorate();
        })();
        return;
      }
      if(a === 'p'){ sv('cxPin', isP ? pins.filter(x=> x !== k) : [k, ...pins.filter(x=> x !== k)]); }
      if(a === 'a'){ sv('cxArch', isA ? arch.filter(x=> x !== k) : [...arch, k]); if(!isA) sv('cxPin', pins.filter(x=> x !== k)); }
      w.remove(); decorate();
    });
    document.body.appendChild(w);
  }
  function decorate(){
    const list = document.getElementById('chatList'); if(!list) return;
    const q = ((document.getElementById('chatSearch') || {}).value || '').trim();
    const pins = ld('cxPin'), arch = ld('cxArch');
    const rows = Array.from(list.querySelectorAll('.chatRow[data-name]')).filter(r=> r.getAttribute('data-name') !== myName);
    let archN = 0, archU = 0, first = null;
    if(showArch && !rows.some(r=> arch.includes(kOf(r.getAttribute('data-name'))))) showArch = false; // last archived chat nikal gayi -> normal list
    rows.forEach(r=>{
      const k = kOf(r.getAttribute('data-name')), isA = arch.includes(k), isP = pins.includes(k);
      const u = Number((r.querySelector('.chatUnread') || {}).textContent) || 0;
      if(isA){ archN++; archU += u; }
      r.style.display = q ? '' : (showArch ? (isA ? '' : 'none') : (isA ? 'none' : ''));
      const nm = r.querySelector('.chatRowName');
      if(nm && isP && !isA && !nm.querySelector('.cxPinMark')){ const s = document.createElement('span'); s.className = 'cxPinMark'; s.textContent = '📌'; nm.appendChild(s); }
    });
    // pinned upar (pin order me)
    const vis = rows.filter(r=> r.style.display !== 'none');
    first = vis.find(r=> !pins.includes(kOf(r.getAttribute('data-name'))));
    if(!showArch && first){ pins.slice().reverse().forEach(pk=>{ const r = vis.find(x=> kOf(x.getAttribute('data-name')) === pk); if(r) list.insertBefore(r, vis.find(x=> !pins.includes(kOf(x.getAttribute('data-name')))) || first); }); }
    const old = list.querySelector('.cxArchRow'); if(old) old.remove();
    if(!q && (archN || showArch)){
      const b = document.createElement('button'); b.type = 'button'; b.className = 'cxArchRow';
      b.innerHTML = showArch ? '<span>←</span><span>Wapas chats</span>' : '<span>📦</span><span>Archived</span><b class="' + (archU ? 'u' : '') + '">' + (archU || archN) + '</b>';
      b.addEventListener('click', (e)=>{ e.stopPropagation(); showArch = !showArch; decorate(); try{ list.scrollTop = 0; }catch(_){} });
      const sr = Array.from(list.children).find(c=> c.classList && c.classList.contains('chatRow') && c.getAttribute('data-name') === myName);
      list.insertBefore(b, sr ? sr.nextSibling : list.firstChild);
    }
  }
  // long-press
  document.addEventListener('pointerdown', (e)=>{
    const r = e.target.closest && e.target.closest('#chatList .chatRow[data-name]'); if(!r || r.getAttribute('data-name') === myName) return;
    sx = e.clientX; sy = e.clientY; clearTimeout(tm);
    tm = setTimeout(()=>{ lp = true; try{ navigator.vibrate && navigator.vibrate(15); }catch(_){} menu(r.getAttribute('data-name')); }, 500);
  }, true);
  document.addEventListener('pointermove', (e)=>{ if(tm && Math.hypot(e.clientX - sx, e.clientY - sy) > 10){ clearTimeout(tm); tm = 0; } }, true);
  ['pointerup', 'pointercancel'].forEach(t=> document.addEventListener(t, ()=>{ clearTimeout(tm); tm = 0; }, true));
  document.addEventListener('click', (e)=>{ if(lp && e.target.closest && e.target.closest('#chatList')){ e.preventDefault(); e.stopPropagation(); } lp = false; }, true);
  document.addEventListener('contextmenu', (e)=>{ if(e.target.closest && e.target.closest('#chatList .chatRow')) e.preventDefault(); }, true);
  // chatRenderInbox ke baad decorate
  const prev = chatRenderInbox;
  chatRenderInbox = function(){ const r = prev.apply(this, arguments); try{ decorate(); }catch(e){} return r; };
  // chat band/khulne par archive view reset
  const o = chatOpenInbox; if(typeof o === 'function'){ chatOpenInbox = function(){ showArch = false; return o.apply(this, arguments); }; }
})();

/* ===== CHAT PLUS 20: THEME 🌙 Dark / ☀️ Light / 🌓 Auto (source: NataliiaKozak/Final_project_ — dark/light toggle + system preference) =====
   Default = Dark (pehle jaisa, eye-friendly). Chats screen ke header me ek button: dabao = Dark -> Light -> Auto (phone ki setting follow).
   Sirf #chatOverlay badalta hai (camera / call / photo editor ke full-screen panels dark hi rehte hain). Save: localStorage 'cxTheme'.
   Colours badalne ho to neeche #chatOverlay[data-cxth="light"]{--eb-*, --panel...} variables. */
(function chatPlus20(){
  if(window.__cxPlus20) return; window.__cxPlus20 = 1;
  const MODES = ['dark', 'light', 'auto'], ICO = { dark: '🌙', light: '☀️', auto: '🌓' }, LBL = { dark: 'Dark theme', light: 'Light theme', auto: 'Auto (phone ke hisaab se)' };
  const getMode = ()=>{ try{ const m = localStorage.getItem('cxTheme'); return MODES.includes(m) ? m : 'dark'; }catch(e){ return 'dark'; } };
  let mode = getMode();
  const mq = (typeof matchMedia === 'function') ? matchMedia('(prefers-color-scheme: light)') : null;
  const eff = ()=> mode === 'auto' ? (mq && mq.matches ? 'light' : 'dark') : mode;
  if(!document.getElementById('cxC20Style')){
    const s = document.createElement('style'); s.id = 'cxC20Style';
    s.textContent = '#chatOverlay[data-cxth="light"]{--eb-bg:#f3f4f6;--eb-panel:#ffffff;--eb-bubble-them:#ffffff;--eb-bubble-me:#d8e6f6;--eb-text:#1d1e22;--eb-dim:#6b6e76;--eb-line:#dcdee3;'
      + '--panel:#ffffff;--border:#dcdee3;--white:#1d1e22;--text:#2a2c31;--muted:#6b6e76;--bg:#f3f4f6;color-scheme:light}'
      + '#chatOverlay[data-cxth="light"] .chatComposer #chatInput{caret-color:#1d1e22!important}'
      + '#chatOverlay[data-cxth="light"] .chatComposer .cxMenu{background:#ffffff!important;border:1px solid #dcdee3!important;box-shadow:0 10px 28px rgba(0,0,0,.18)!important}'
      + '#chatOverlay[data-cxth="light"] .chatComposer #chatSendBtn,#chatOverlay[data-cxth="light"] .chatNewPill,#chatOverlay[data-cxth="light"] .chatUnread{background:#d8e6f6!important;color:#1d1e22!important}'
      + '#chatOverlay[data-cxth="light"] .cxArchRow{color:#1d1e22!important;border-bottom-color:#dcdee3!important}'
      + '#chatOverlay[data-cxth="light"] .cxArchRow b{background:#e3e5ea!important;color:#333}'
      + '#chatOverlay[data-cxth="light"] .cxArchRow b.u{background:#25a56a!important;color:#fff}'
      + '#chatOverlay[data-cxth="light"] .chatSupport{color:#4a5568!important}'
      + '#cxThemeBtn{font-size:18px}';
    document.head.appendChild(s);
  }
  function apply(){
    const ov = document.getElementById('chatOverlay'); if(ov) ov.setAttribute('data-cxth', eff());
    const b = document.getElementById('cxThemeBtn'); if(b){ b.textContent = ICO[mode]; b.title = LBL[mode]; b.setAttribute('aria-label', LBL[mode]); }
    try{ const t = document.querySelector('#chatOverlay'); if(t) t.style.colorScheme = eff(); }catch(e){}
  }
  function inject(){
    const head = document.querySelector('#chatInbox .chatHead'); if(!head) return;
    if(!document.getElementById('cxThemeBtn')){
      const b = document.createElement('button'); b.type = 'button'; b.id = 'cxThemeBtn'; b.className = 'chatIconBtn';
      const lock = document.getElementById('chatLockBtn'); head.insertBefore(b, lock || null);
      b.addEventListener('click', ()=>{
        mode = MODES[(MODES.indexOf(mode) + 1) % MODES.length];
        try{ localStorage.setItem('cxTheme', mode); }catch(e){}
        apply();
        try{ if(typeof toast === 'function') toast(ICO[mode] + ' ' + LBL[mode]); }catch(e){}
      });
    }
    apply();
  }
  if(mq){ const f = ()=>{ if(mode === 'auto') apply(); }; mq.addEventListener ? mq.addEventListener('change', f) : (mq.addListener && mq.addListener(f)); }
  cxPoll('chat', ()=>{ try{ inject(); }catch(e){} }, 600);
  inject();
})();

/* ===== CHAT PLUS 21: CALL SPEAKING INDICATOR + "MUTE HAI" HINT (source: jovannilil/discord-clone — "speaking indicator (green ring) via Web Audio AnalyserNode") =====
   Voice/video call me samne wala bolta hai to uske avatar par hara ring + video par hara border.
   Tum mute ho aur bol rahe ho to chhota hint "🎙️ Mute hai — aap bol rahe ho" (har 8s me max 1 baar).
   Sirf dekhne ka overlay: audio ko kahin connect nahi karta (playback/quality par asar nahi). Call band hote hi sab band. */
(function chatPlus21(){
  if(window.__cxPlus21) return; window.__cxPlus21 = 1;
  if(!document.getElementById('cxC21Style')){
    const s = document.createElement('style'); s.id = 'cxC21Style';
    s.textContent = '#callAv{transition:box-shadow .15s}'
      + '#callAv.cxSpk{box-shadow:0 0 0 4px #25d366,0 0 22px rgba(37,211,102,.75)!important;border-radius:50%}'
      + '#callOv.cxSpkR #callRemote{box-shadow:inset 0 0 0 3px #25d366}'
      + '#cxMuteHint{position:absolute;left:50%;bottom:calc(120px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:rgba(0,0,0,.72);color:#fff;padding:9px 16px;border-radius:20px;font-size:14px;z-index:5;opacity:0;pointer-events:none;transition:opacity .2s;white-space:nowrap}'
      + '#cxMuteHint.on{opacity:1}';
    document.head.appendChild(s);
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  let ctx = null, rem = null, loc = null, locClone = null, remAt = 0, remOn = false, locAt = 0, hintAt = 0, hintT = 0;
  function mkAn(stream){
    if(!AC || !stream) return null;
    try{
      if(!ctx) ctx = new AC();
      if(ctx.state === 'suspended' && ctx.resume) ctx.resume().catch(()=>{});
      const src = ctx.createMediaStreamSource(stream), an = ctx.createAnalyser();
      an.fftSize = 512; src.connect(an); // destination se connect NAHI
      return { stream, src, an, buf: new Uint8Array(an.fftSize) };
    }catch(e){ return null; }
  }
  function rms(o){
    if(!o) return 0;
    try{ o.an.getByteTimeDomainData(o.buf); }catch(e){ return 0; }
    let sum = 0; for(let i = 0; i < o.buf.length; i++){ const v = (o.buf[i] - 128) / 128; sum += v * v; }
    return Math.sqrt(sum / o.buf.length);
  }
  function drop(o){ try{ o && o.src && o.src.disconnect(); }catch(e){} }
  function reset(){
    drop(rem); drop(loc); rem = loc = null;
    try{ locClone && locClone.stop(); }catch(e){} locClone = null;
    remOn = false; remAt = locAt = 0;
    const av = document.getElementById('callAv'), ov = document.getElementById('callOv'), h = document.getElementById('cxMuteHint');
    if(av) av.classList.remove('cxSpk'); if(ov) ov.classList.remove('cxSpkR'); if(h) h.classList.remove('on');
  }
  function hint(){
    const ov = document.getElementById('callOv'); if(!ov) return;
    let h = document.getElementById('cxMuteHint');
    if(!h){ h = document.createElement('div'); h.id = 'cxMuteHint'; h.textContent = '🎙️ Mute hai — aap bol rahe ho'; ov.appendChild(h); }
    h.classList.add('on'); clearTimeout(hintT); hintT = setTimeout(()=> h.classList.remove('on'), 2800);
  }
  function tick(){
    const ov = document.getElementById('callOv');
    if(!ov || !ov.classList.contains('open')){ if(rem || loc || locClone) reset(); return; }
    const now = Date.now(), S = window.__cxCallS && window.__cxCallS();
    // samne wala
    const r = document.getElementById('callRemote'), rs = r && r.srcObject;
    if(rs && rs.getAudioTracks && rs.getAudioTracks().length){
      if(!rem || rem.stream !== rs){ drop(rem); rem = mkAn(rs); }
      if(rem && rms(rem) > 0.035) remAt = now;
    }
    const on = now - remAt < 350;
    if(on !== remOn){ remOn = on; const av = document.getElementById('callAv'); if(av) av.classList.toggle('cxSpk', on); ov.classList.toggle('cxSpkR', on); }
    // apna mic (mute me bhi sunne ke liye alag clone track — original track ko nahi chhedta)
    const lt = S && S.stream && S.stream.getAudioTracks && S.stream.getAudioTracks()[0];
    if(lt){
      if(!locClone || locClone.__src !== lt.id){
        try{ locClone && locClone.stop(); }catch(e){} drop(loc); loc = null;
        try{ locClone = lt.clone(); locClone.enabled = true; locClone.__src = lt.id; loc = mkAn(new MediaStream([locClone])); }catch(e){ locClone = null; }
      }
      const muted = !lt.enabled;
      if(loc && muted && rms(loc) > 0.05){ if(!locAt) locAt = now; if(now - locAt > 500 && now - hintAt > 8000){ hintAt = now; hint(); } } else locAt = 0;
    }
  }
  cxPoll('call', ()=>{ try{ tick(); }catch(e){} }, 120);
  window.__cxP21 = { tick, reset }; // test ke liye
})();

/* ===== CHAT PLUS 22: CALLS LOG (📞 Calls list — WhatsApp "Calls" tab jaisi) (source: iampawan/FlutterWhatsAppClone — Camera|Chats|Status|Calls tabs) =====
   Chats header me 📞 button -> saari recent calls ki list: kaun, voice/video, aayi/gayi, missed (laal), duration, kab.
   Row dabao = us chat me jao; 📞 / 🎥 button = wapas call. 'Clear' = list saaf.
   Log is device me banta hai (call ke dauraan window.__cxCallS() dekh kar), localStorage 'cxCallLog:<me>', max 100. Purani calls (jo is device par nahi hui) nahi dikhengi.
   App ka chat-andar wala call bubble waise hi rehta hai (usko nahi chheda). */
(function chatPlus22(){
  if(window.__cxPlus22) return; window.__cxPlus22 = 1;
  const me = ()=>{ try{ return chatMyKey(); }catch(e){ return 'me'; } };
  const KEY = ()=> 'cxCallLog:' + me();
  const load = ()=>{ try{ const a = JSON.parse(localStorage.getItem(KEY()) || '[]'); return Array.isArray(a) ? a : []; }catch(e){ return []; } };
  const save = (a)=>{ try{ localStorage.setItem(KEY(), JSON.stringify(a.slice(0, 100))); }catch(e){} };
  const esc = (t)=> String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  if(!document.getElementById('cxC22Style')){
    const s = document.createElement('style'); s.id = 'cxC22Style';
    s.textContent = '#cxCallsSheet{position:absolute;inset:0;z-index:60;display:flex;flex-direction:column;background:var(--eb-bg,#101114);color:var(--eb-text,#cfd0d4)}'
      + '#cxCallsSheet .cxCH{display:flex;align-items:center;gap:10px;padding:calc(10px + env(safe-area-inset-top,0px)) 12px 10px;border-bottom:1px solid var(--eb-line,#25272d)}'
      + '#cxCallsSheet .cxCH b{flex:1;font-size:19px}'
      + '#cxCallsSheet .cxCH button{background:transparent;border:0;color:inherit;font-size:16px;padding:6px 8px}'
      + '#cxCallsList{flex:1;overflow-y:auto;overscroll-behavior:contain}'
      + '.cxCRow{display:flex;align-items:center;gap:12px;padding:12px 14px;border-bottom:1px solid var(--eb-line,#25272d)}'
      + '.cxCRow .cxCI{font-size:18px;width:26px;text-align:center}'
      + '.cxCRow .cxCM{flex:1;min-width:0}.cxCRow .cxCN{font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
      + '.cxCRow .cxCS{font-size:13.5px;color:var(--eb-dim,#8b8d95);margin-top:2px}'
      + '.cxCRow.miss .cxCN,.cxCRow.miss .cxCI{color:#ef5350}'
      + '.cxCRow .cxCB{background:transparent;border:0;color:inherit;font-size:20px;padding:6px 8px}'
      + '#cxCallsEmpty{padding:40px 20px;text-align:center;color:var(--eb-dim,#8b8d95)}'
      + '#cxCallsBtn{font-size:18px}';
    document.head.appendChild(s);
  }
  // ---- log banana: call session ko dekhte raho ----
  let cur = null;
  function fin(s){
    if(!s || !s.peerName) return;
    const secs = s.t0 ? Math.max(1, Math.round((s.__last - s.t0) / 1000)) : 0;
    const st = secs > 0 ? 'ok' : (s.incoming ? 'miss' : 'noans');
    const a = load(); a.unshift({ id: s.id || String(s.__start), n: s.peerName, k: s.peerKey, t: s.type === 'v' ? 'v' : 'a', in: !!s.incoming, st, s: secs, ts: s.__start });
    save(a); render();
  }
  function watch(){
    const S = window.__cxCallS && window.__cxCallS();
    if(S){
      if(!cur || cur.id !== S.id){ if(cur) fin(cur); cur = { id: S.id, peerName: S.peerName, peerKey: S.peerKey, type: S.type, incoming: S.incoming, __start: Date.now() }; }
      cur.incoming = S.incoming; cur.t0 = S.t0 || cur.t0; cur.__last = Date.now();
    }else if(cur){ const c = cur; cur = null; fin(c); }
  }
  setInterval(()=>{ if(window.__cxCallS && !window.__cxCallS() && !cur) return; try{ watch(); }catch(e){} }, 400);
  // ---- UI ----
  const fmtT = (ts)=>{
    const d = new Date(ts), n = new Date(), hm = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const day = (x)=> new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
    const diff = Math.round((day(n) - day(d)) / 86400000);
    return (diff === 0 ? 'Aaj' : diff === 1 ? 'Kal' : d.toLocaleDateString([], { day: 'numeric', month: 'short' })) + ', ' + hm;
  };
  const fmtD = (s)=>{ s = Number(s) || 0; const m = Math.floor(s / 60), r = s % 60; return m + ':' + String(r).padStart(2, '0'); };
  function render(){
    const box = document.getElementById('cxCallsList'); if(!box) return;
    const a = load();
    if(!a.length){ box.innerHTML = '<div id="cxCallsEmpty">Abhi koi call nahi.<br>Is device par jo calls hongi yahan dikhengi.</div>'; return; }
    box.innerHTML = a.map((c, i)=>{
      const miss = c.st === 'miss';
      const dir = c.in ? '↙' : '↗';
      const stx = c.st === 'ok' ? (c.in ? 'Aayi' : 'Gayi') + ' · ' + fmtD(c.s) : (miss ? 'Missed / decline' : 'Jawab nahi');
      return '<div class="cxCRow' + (miss ? ' miss' : '') + '" data-i="' + i + '"><div class="cxCI">' + dir + '</div><div class="cxCM"><div class="cxCN">' + esc(c.n) + '</div><div class="cxCS">' + (c.t === 'v' ? '🎥 Video' : '📞 Voice') + ' · ' + esc(stx) + ' · ' + esc(fmtT(c.ts)) + '</div></div>'
        + '<button type="button" class="cxCB" data-back="a" aria-label="Voice call">📞</button><button type="button" class="cxCB" data-back="v" aria-label="Video call">🎥</button></div>';
    }).join('');
  }
  function open(){
    const ov = document.getElementById('chatOverlay'); if(!ov || document.getElementById('cxCallsSheet')) return;
    const sh = document.createElement('div'); sh.id = 'cxCallsSheet';
    sh.innerHTML = '<div class="cxCH"><button type="button" id="cxCallsBack" aria-label="Wapas">←</button><b>📞 Calls</b><button type="button" id="cxCallsClr">Clear</button></div><div id="cxCallsList"></div>';
    ov.appendChild(sh); render();
    sh.querySelector('#cxCallsBack').addEventListener('click', close);
    sh.querySelector('#cxCallsClr').addEventListener('click', ()=>{ if(!load().length) return; if(confirm('Calls ki list saaf kar du? (chat ke andar ke call messages rahenge)')){ save([]); render(); } });
    sh.querySelector('#cxCallsList').addEventListener('click', async (e)=>{
      const row = e.target.closest && e.target.closest('.cxCRow'); if(!row) return;
      const c = load()[Number(row.getAttribute('data-i'))]; if(!c) return;
      const back = e.target.closest('[data-back]'); const kind = back && back.getAttribute('data-back');
      close();
      try{ await chatOpenConv(c.n); }catch(_){ return; }
      if(kind){ setTimeout(()=>{ const b = document.getElementById(kind === 'v' ? 'cxCallV' : 'cxCallA'); if(b) b.click(); }, 450); }
    });
  }
  function close(){ const sh = document.getElementById('cxCallsSheet'); if(sh) sh.remove(); }
  function inject(){
    const head = document.querySelector('#chatInbox .chatHead'); if(!head) return;
    if(document.getElementById('cxCallsBtn')) return;
    const b = document.createElement('button'); b.type = 'button'; b.id = 'cxCallsBtn'; b.className = 'chatIconBtn'; b.textContent = '📞'; b.setAttribute('aria-label', 'Calls');
    b.addEventListener('click', open);
    const ref = document.getElementById('cxThemeBtn') || document.getElementById('chatLockBtn');
    head.insertBefore(b, ref || null);
  }
  cxPoll('chat', ()=>{ try{ inject(); }catch(e){} }, 600); inject();
  window.__cxP22 = { watch, load, render, open };
})();


/* ===== CHAT PLUS 23: MESSAGE SOUND 🔔/🔕 — ICQ "uh-oh" (source: Felix-Helleckes/ICQ — classic ICQ notification sound + global 🔔/🔕 toggle) =====
   Naya message aate hi chhoti si "uh-oh" awaaz (Web Audio se bani, koi audio file nahi). Chats header me 🔔/🔕 button (📞 ke pehle) = on/off.
   Default = ON. Save: localStorage 'cxSnd'. Mute/Block kiye chat par awaaz NAHI. Ek saath bahut messages aaye to 1.2s me ek hi baar.
   - Chat band / dusri screen / doosre chat ka message aaye -> pooori awaaz.  - Jis chat ko dekh rahe ho uska message aaye -> halki (soft) awaaz.
   - Phone locked / app background me ho to system notification apni awaaz bajata hai (yahan kuch nahi).
   Awaaz ko badalna ho to neeche NOTES / VOL. */
(function chatPlus23(){
  if(window.__cxPlus23) return; window.__cxPlus23 = 1;
  const NOTES = [[740, 0, .12], [587, .13, .2]], VOL = .2, SOFT = .45, GAP = 1200;
  const on = ()=>{ try{ return localStorage.getItem('cxSnd') !== '0'; }catch(e){ return true; } };
  let ac = null, lastAt = 0;
  function ctx(){
    if(ac) return ac;
    const AC = window.AudioContext || window.webkitAudioContext; if(!AC) return null;
    try{ ac = new AC(); }catch(e){ ac = null; }
    return ac;
  }
  function ding(soft){
    const c = ctx(); if(!c) return false;
    try{ if(c.state === 'suspended') c.resume(); }catch(e){}
    const t0 = c.currentTime + .01, v = VOL * (soft ? SOFT : 1);
    NOTES.forEach(n=>{
      const o = c.createOscillator(), g = c.createGain();
      o.type = 'sine'; o.frequency.setValueAtTime(n[0], t0 + n[1]);
      g.gain.setValueAtTime(.0001, t0 + n[1]);
      g.gain.exponentialRampToValueAtTime(v, t0 + n[1] + .015);
      g.gain.exponentialRampToValueAtTime(.0001, t0 + n[1] + n[2]);
      o.connect(g); g.connect(c.destination); o.start(t0 + n[1]); o.stop(t0 + n[1] + n[2] + .03);
    });
    return true;
  }
  function maybe(key, soft){
    if(!on() || document.hidden) return false;
    try{ if((window.cxIsMuted && window.cxIsMuted(key)) || (window.cxIsBlocked && window.cxIsBlocked(key))) return false; }catch(e){}
    const now = Date.now(); if(now - lastAt < GAP) return false; lastAt = now;
    return ding(soft);
  }
  // browser autoplay rule: pehle touch par audio unlock
  ['pointerdown', 'keydown'].forEach(ev=> document.addEventListener(ev, ()=>{ const c = ctx(); try{ if(c && c.state === 'suspended') c.resume(); }catch(e){} }, { capture: true, passive: true }));
  // 1) chat ke bahar / dusre chat ka message
  const prevN = chatNotifyIncoming;
  chatNotifyIncoming = function(e, key){ try{ maybe(key, false); }catch(_){} return prevN.apply(this, arguments); };
  // 2) abhi khula chat — uska naya message (pehle koi notify hota hi nahi tha)
  const prevI = chatOnIdx;
  chatOnIdx = function(val){
    let hit = null;
    try{
      if(!chatIdxFirst && chatView === 'conv' && chatPeer && !document.hidden){
        const k = chatPeer.key, cur = (val || {})[k], old = chatIdx[k], me = chatMyKey();
        if(cur && cur.f && cur.f !== me && (!old || cur.ts !== old.ts)) hit = k;
      }
    }catch(_){}
    const r = prevI.apply(this, arguments);
    if(hit){ try{ maybe(hit, true); }catch(_){} }
    return r;
  };
  // 3) header button
  if(!document.getElementById('cxC23Style')){
    const st = document.createElement('style'); st.id = 'cxC23Style'; st.textContent = '#cxSndBtn{font-size:18px}'; document.head.appendChild(st);
  }
  function paint(){ const b = document.getElementById('cxSndBtn'); if(!b) return; const o = on(); b.textContent = o ? '🔔' : '🔕'; b.title = o ? 'Message sound ON' : 'Message sound OFF'; b.setAttribute('aria-label', b.title); }
  function inject(){
    const head = document.querySelector('#chatInbox .chatHead'); if(!head) return;
    if(document.getElementById('cxSndBtn')) return;
    const b = document.createElement('button'); b.type = 'button'; b.id = 'cxSndBtn'; b.className = 'chatIconBtn';
    b.addEventListener('click', ()=>{ const o = !on(); try{ localStorage.setItem('cxSnd', o ? '1' : '0'); }catch(e){} paint(); if(o) ding(false); });
    const ref = document.getElementById('cxCallsBtn') || document.getElementById('cxThemeBtn') || document.getElementById('chatLockBtn');
    head.insertBefore(b, ref || null); paint();
  }
  cxPoll('chat', ()=>{ try{ inject(); }catch(e){} }, 600); inject();
  window.__cxP23 = { ding, maybe, on };
})();


/* ===== CHAT PLUS 14: ADMIN CHAT VIEWER (read-only) =====
   Sirf Room Admin (loadRoomMeta().admin == myName): inbox header me 👁 button -> sab members ki 1-to-1 chats ki list -> tap karke
   aakhri 100 messages READ-ONLY (edit/delete/send nahi). Har view `rooms/<room>/_adminViewLog` me log hota hai (by, pair, ts).
   Transparency: chat ke andar note me likha hai ki Admin dekh sakta hai. Member ko ye button dikhta hi nahi.
   Firebase rules me Admin uid ko `_chats` / `_chatIdx` READ allow hona chahiye (FIREBASE_RULES_CHAT.txt owner-only ho to). */
(function chatPlus14(){
  let isAdm = false, lastChk = 0;
  const $ = (id)=> document.getElementById(id);
  const esc = (t)=> (typeof escapeHtml === 'function' ? escapeHtml(String(t == null ? '' : t)) : String(t == null ? '' : t).replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])));
  async function checkAdmin(){
    if(Date.now() - lastChk < 5000) return isAdm;
    lastChk = Date.now();
    try{ const m = await loadRoomMeta(); isAdm = !!(m && m.admin && typeof myName === 'string' && (m.admin === myName || chatSeenKey(m.admin) === chatSeenKey(myName))); }catch(e){ isAdm = false; }
    return isAdm;
  }
  function prev(m){ return m.k === 'i' ? '📷 Photo' : m.k === 'v' ? '🎬 Video' : m.k === 'a' ? '🎤 Voice message' : m.k === 'f' ? '📄 ' + ((m.a && m.a.n) || 'File') : m.k === 'c' ? '📞 Call' : String(m.t || ''); }
  function ensurePanel(){
    let p = $('cxAdminView'); if(p) return p;
    p = document.createElement('div'); p.id = 'cxAdminView';
    p.style.cssText = 'display:none;position:fixed;inset:0;z-index:900;background:var(--bg,#08070a);color:var(--text,#c6c3cb);flex-direction:column;font-family:var(--font-main,system-ui,sans-serif);';
    p.innerHTML = '<div style="display:flex;align-items:center;gap:10px;padding:calc(10px + env(safe-area-inset-top,0px)) 12px 10px;background:var(--panel,#111013);border-bottom:1px solid var(--border,#333038)"><button type="button" id="cxAvBack" class="chatIconBtn">←</button><div style="flex:1;min-width:0"><div id="cxAvTitle" style="font-weight:800;font-size:16px;color:var(--white,#eeecf0)">👁 Admin: sab chats</div><div style="font-size:11.5px;color:var(--muted,#aaa5ad)">Read-only · har view log hota hai</div></div></div><div id="cxAvBody" style="flex:1;overflow:auto;padding:10px 12px;max-width:640px;width:100%;margin:0 auto;box-sizing:border-box"></div>';
    document.body.appendChild(p);
    $('cxAvBack').onclick = ()=>{ if(p._view === 'conv') showList(); else p.style.display = 'none'; };
    return p;
  }
  function nameOfKey(k, map){ return (map && map[k]) || k; }
  async function showList(){
    const p = ensurePanel(); p._view = 'list'; p.style.display = 'flex';
    $('cxAvTitle').textContent = '👁 Admin: sab chats';
    const body = $('cxAvBody'); body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted,#aaa5ad)">Load ho raha hai…</div>';
    try{
      await window.__fbReadyPromise;
      const members = (typeof chatMembers !== 'undefined' ? chatMembers : []).slice();
      const me = chatMyKey(); if(!members.find(m=>m.key === me)) members.push({ name: myName, key: me });
      const names = {}; members.forEach(m=> names[m.key] = m.name);
      const pairs = new Map();
      const base = chatBase();
      await Promise.all(members.map(async m=>{
        const idx = await window.__fbGet(`${base}/_chatIdx/${m.key}`) || {};
        Object.keys(idx).forEach(k=>{
          const e = idx[k] || {}; if(e.n && !names[k]) names[k] = e.n;
          const pair = chatPairKey(m.key, k); const ts = Number(e.ts) || 0;
          const cur = pairs.get(pair);
          if(!cur || ts > cur.ts) pairs.set(pair, { pair, a: m.key, b: k, ts, p: e.p || e.t || '' });
        });
      }));
      const arr = Array.from(pairs.values()).sort((x,y)=> y.ts - x.ts);
      p._names = names;
      if(!arr.length){ body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted,#aaa5ad)">Abhi koi chat nahi mili.</div>'; return; }
      body.innerHTML = arr.map(r=>`<button type="button" data-pair="${esc(r.pair)}" data-a="${esc(r.a)}" data-b="${esc(r.b)}" style="display:block;width:100%;text-align:left;padding:12px;margin-bottom:8px;border-radius:12px;border:1px solid var(--border,#333038);background:var(--panel2,#1a181d);color:inherit;cursor:pointer"><div style="font-weight:800;color:var(--white,#eeecf0)">${esc(nameOfKey(r.a, names))} ↔ ${esc(nameOfKey(r.b, names))}</div><div style="font-size:12px;color:var(--muted,#aaa5ad);margin-top:3px">${r.ts ? esc(new Date(r.ts).toLocaleString('en-IN')) : ''}</div></button>`).join('');
      body.querySelectorAll('button[data-pair]').forEach(b=> b.onclick = ()=> openPair(b.dataset.pair, b.dataset.a, b.dataset.b));
    }catch(e){ console.error(e); body.innerHTML = '<div style="padding:20px;text-align:center;color:#ef4444">Chats load nahi hui. Firebase rules me Admin ko read allow hai?</div>'; }
  }
  async function openPair(pair, a, b){
    const p = ensurePanel(); p._view = 'conv';
    const names = p._names || {};
    $('cxAvTitle').textContent = nameOfKey(a, names) + ' ↔ ' + nameOfKey(b, names);
    const body = $('cxAvBody'); body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted,#aaa5ad)">Load ho raha hai…</div>';
    try{
      const base = chatBase();
      const arr = await window.__fbChatOlder(`${base}/_chats/${pair}/m`, '~', 100);
      try{ window.__fbPush(`${base}/_adminViewLog`, { by: myName, pair, ts: Date.now() }); }catch(e){}
      if(!arr.length){ body.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted,#aaa5ad)">Is chat me koi message nahi.</div>'; return; }
      let lastDay = '';
      body.innerHTML = arr.map(([id, m])=>{
        m = m || {}; const d = new Date(Number(m.ts) || 0), day = d.toDateString();
        const sep = day !== lastDay ? `<div style="text-align:center;font-size:11px;color:var(--muted,#aaa5ad);margin:10px 0 4px">${esc(d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}))}</div>` : ''; lastDay = day;
        return sep + `<div style="margin:6px 0;padding:8px 10px;border-radius:10px;background:var(--panel2,#1a181d);border:1px solid var(--border,#333038)"><div style="font-size:11.5px;font-weight:800;color:var(--accent,#fbbf24)">${esc(nameOfKey(m.f, names))} <span style="font-weight:600;color:var(--muted,#aaa5ad)">· ${esc(d.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}))}</span></div><div style="margin-top:3px;word-break:break-word;white-space:pre-wrap">${esc(prev(m))}</div></div>`;
      }).join('');
      body.scrollTop = body.scrollHeight;
    }catch(e){ console.error(e); body.innerHTML = '<div style="padding:20px;text-align:center;color:#ef4444">Messages load nahi hue (rules/network).</div>'; }
  }
  async function inject(){
    const head = document.querySelector('#chatInbox .chatHead'); if(!head) return;
    const adm = await checkAdmin(); let b = $('cxAdminViewBtn');
    if(!adm){ if(b) b.remove(); return; }
    if(b) return;
    b = document.createElement('button'); b.type = 'button'; b.id = 'cxAdminViewBtn'; b.className = 'chatIconBtn'; b.textContent = '👁'; b.title = 'Admin: sab chats dekho'; b.setAttribute('aria-label', 'Admin chat viewer');
    b.addEventListener('click', ()=>{ if(typeof chatHasPin === 'function' && chatHasPin() && !chatUnlocked) return; showList(); });
    const lock = $('chatLockBtn'); head.insertBefore(b, lock || null);
  }
  cxPoll('chat', ()=>{ try{ inject(); }catch(e){} }, 1500);
  window.__cxAdminView = { showList, openPair, checkAdmin };
})();


/* ===== CHAT PLUS 15: VIDEO CALL — screen swap + camera look auto + pre-call face preview =====
   1) Call me apni chhoti screen ya samne wali chhoti screen par tap = dono swap (sirf tumhare phone par, samne wale ko asar nahi).
   2) Camera ka saved Grade/LUT/Beauty video call me auto lagta hai (window.cxCallLookOn). 🎨 button se call me ON/OFF.
   3) 🎥 dabane par pehle apna face preview (look ke saath) -> "Call karo" / ✕. Ringing ke dauran bhi apna face bada dikhta hai. */
(function chatPlus15(){
  const $ = (id)=> document.getElementById(id);
  const toast = (m)=>{ try{ chatToastMsg(m); }catch(e){} };
  let lookOff = false, bound = false, pre = null, go = false;
  window.cxCallLookOn = ()=> !lookOff && !!(window.cxGradeActive && window.cxGradeActive());
  const S = ()=> (window.__cxCallS && window.__cxCallS()) || null;

  const st = document.createElement('style');
  st.textContent = `
  .callOv.vid.conn #callRemote,.callOv.vid.conn #callLocal{cursor:pointer;}
  .callOv.cxSwap #callRemote{inset:auto;right:14px;top:calc(14px + env(safe-area-inset-top,0px));width:96px;height:132px;border-radius:14px;border:2px solid #fff4;z-index:3;}
  .callOv.cxSwap #callLocal{right:auto;left:0;top:0;width:100%;height:100%;border-radius:0;border:0;z-index:1;}
  .callOv.vid.cxPre #callLocal{display:block;right:auto;left:0;top:0;width:100%;height:100%;border-radius:0;border:0;z-index:1;}
  #cxPreCall{position:fixed;inset:0;z-index:1100;display:none;flex-direction:column;background:#000;color:#fff;font-family:var(--font-main,system-ui,sans-serif);}
  #cxPreCall.open{display:flex;}
  #cxPreCall canvas{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
  #cxPreCall .pcT{position:relative;z-index:2;text-align:center;padding:calc(18px + env(safe-area-inset-top,0px)) 16px 0;font-weight:800;text-shadow:0 2px 8px #000a;}
  #cxPreCall .pcT small{display:block;font-weight:600;opacity:.8;margin-top:4px;font-size:12px;}
  #cxPreCall .pcB{position:relative;z-index:2;margin-top:auto;display:flex;gap:22px;justify-content:center;padding:0 16px calc(32px + env(safe-area-inset-bottom,0px));}
  #cxPreCall .pcB button{width:64px;height:64px;border-radius:50%;border:0;font-size:26px;cursor:pointer;color:#fff;}
  #cxPreCall .pcX{background:#ef4444;} #cxPreCall .pcOk{background:#22c55e;}`;
  document.head.appendChild(st);

  function stopPre(){
    if(!pre) return;
    const p = pre; pre = null; cancelAnimationFrame(p.raf);
    try{ p.stream.getTracks().forEach(t => t.stop()); p.vid.srcObject = null; }catch(e){}
    const o = $('cxPreCall'); if(o) o.classList.remove('open');
  }
  function ensurePre(){
    let o = $('cxPreCall'); if(o) return o;
    o = document.createElement('div'); o.id = 'cxPreCall';
    o.innerHTML = '<canvas id="cxPreCv"></canvas><div class="pcT">Apna face dekh lo<small>Camera ka saved look / Beauty yahan bhi lagta hai</small></div><div class="pcB"><button type="button" class="pcX" id="cxPreNo" aria-label="Cancel">✕</button><button type="button" class="pcOk" id="cxPreGo" aria-label="Video call karo">🎥</button></div>';
    document.body.appendChild(o);
    $('cxPreNo').onclick = stopPre;
    $('cxPreGo').onclick = ()=>{ stopPre(); go = true; const b = $('cxCallV'); if(b) b.click(); go = false; };
    return o;
  }
  async function openPre(){
    if(pre || S()) return;
    const o = ensurePre();
    let stream;
    try{ stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 960 } }, audio: false }); }
    catch(e){ toast('Camera ki permission do.'); return; }
    o.classList.add('open');
    const vid = document.createElement('video'); vid.muted = true; vid.playsInline = true; vid.autoplay = true; vid.srcObject = stream; vid.play().catch(()=>{});
    const cv = $('cxPreCv'), ctx = cv.getContext('2d');
    const f = { canF: ('filter' in ctx), parts: [], n: 0, ms: 16, cap: 960 };
    const none = (window.cxFX && window.cxFX.list.find(x => x.id === 'none')) || (window.cxFX && window.cxFX.list[0]);
    const p = pre = { stream, vid, raf: 0 };
    (function tick(){
      if(pre !== p) return;
      p.raf = requestAnimationFrame(tick);
      const vw = vid.videoWidth, vh = vid.videoHeight; if(!vw || !vh) return;
      const w = Math.min(vw, 720), h = Math.round(vh * w / vw);
      if(cv.width !== w || cv.height !== h){ cv.width = w; cv.height = h; }
      f.n++;
      try{
        ctx.save(); ctx.translate(w, 0); ctx.scale(-1, 1);
        window.cxFX.draw(ctx, vid, w, h, none, f);
        ctx.restore();
        if(window.cxGradeActive && window.cxGradeActive()){ const g = window.cxGradeApply(cv, w, h, f.canF); if(g) ctx.drawImage(g, 0, 0, w, h); }
      }catch(e){ try{ ctx.restore(); }catch(_){} }
    })();
  }
  // 🎥 intercept (capture): pehle preview, "Call karo" par asli call
  document.addEventListener('click', (e)=>{
    const b = e.target && e.target.closest && e.target.closest('#cxCallV');
    if(!b || go) return;
    e.stopImmediatePropagation(); e.preventDefault();
    openPre();
  }, true);

  function ensureLookBtn(){
    const ov = $('callOv'); if(!ov) return;
    const bt = ov.querySelector('.callBtns');
    if(bt && !$('callLook')){
      const b = document.createElement('button'); b.type = 'button'; b.id = 'callLook'; b.className = 'callBtn'; b.textContent = '🎨'; b.setAttribute('aria-label', 'Camera look on/off');
      bt.insertBefore(b, $('callEnd') || null);
      b.addEventListener('click', ()=>{
        if(!(window.cxGradeActive && window.cxGradeActive())){ toast('Camera me koi Grade/LUT set nahi hai.'); return; }
        lookOff = !lookOff; b.style.opacity = lookOff ? '.45' : '1'; toast(lookOff ? '🎨 Camera look OFF' : '🎨 Camera look ON');
        try{ window.cxFxRefresh && window.cxFxRefresh(); }catch(e){}
      });
    }
    if(!bound){
      bound = true;
      ov.addEventListener('click', (e)=>{
        if(!ov.classList.contains('conn') || !ov.classList.contains('vid')) return;
        const small = ov.classList.contains('cxSwap') ? 'callRemote' : 'callLocal';
        if(e.target && e.target.id === small) ov.classList.toggle('cxSwap');
      });
    }
  }
  cxPoll('call', ()=>{
    try{
      ensureLookBtn();
      const ov = $('callOv'); if(!ov) return;
      const s = S(), open = ov.classList.contains('open');
      if(!open){ ov.classList.remove('cxSwap', 'cxPre'); lookOff = false; const lb = $('callLook'); if(lb) lb.style.opacity = '1'; return; }
      const lb = $('callLook'); if(lb) lb.hidden = !(s && s.type === 'v');
      ov.classList.toggle('cxPre', !!(s && s.type === 'v' && !s.incoming && !ov.classList.contains('conn')));
      if(s && s.pc && s.type === 'v' && window.cxFxRefresh){
        const act = !!((window.cxBeautyActive && window.cxBeautyActive()) || window.cxCallLookOn());
        const run = !!(window.cxFxRunning && window.cxFxRunning());
        if(act !== run) window.cxFxRefresh();
      }
    }catch(e){}
  }, 400);
})();

/* ===== CHAT PLUS 20: chat ke ANDAR bhi 🔒 Lock button (header me Aa ke baad) =====
   PIN set hai -> tap = chat band + turant lock (wapas kholne par PIN). PIN set nahi -> PIN set karne ka screen.
   Inbox wala 🔒/🔓 button jaisa tha waisa hi hai. */
(function chatPlus20(){
  function inject(){
    const conv = document.getElementById('chatConv'); if(!conv || conv.hidden) return;
    const h = conv.querySelector('.chatHead'); if(!h) return;
    let b = document.getElementById('cxConvLock');
    if(!b){
      b = document.createElement('button'); b.type = 'button'; b.id = 'cxConvLock'; b.className = 'chatIconBtn'; b.setAttribute('aria-label', 'Chat lock');
      b.addEventListener('click', ()=>{
        try{
          if(chatHasPin()){ chatClose(); }
          else{ chatShowPinPane('set'); }
        }catch(e){}
      });
      h.insertBefore(b, document.getElementById('cxMoreBtn') || null);
    }
    const t = chatHasPin() ? '🔒' : '🔓'; if(b.textContent !== t) b.textContent = t;
  }
  cxPoll('chat', ()=>{ try{ inject(); }catch(e){} }, 800);
})();

